<script setup>
import {ref,computed,watch} from 'vue';
import {cabinetInterval} from '../shared/cabinet-arrange.mjs';
const props=defineProps({item:{type:Object,required:true},furniture:{type:Array,required:true}}),emit=defineEmits(['arrange']);
const referenceId=ref(''),axis=ref('x'),edge=ref('center'),side=ref('after'),gap=ref(.1);
const peers=computed(()=>props.furniture.filter(c=>c.id!==props.item.id));
watch(peers,list=>{if(!list.some(c=>c.id===referenceId.value))referenceId.value=list[0]?.id??'';},{immediate:true});
const projectedGap=computed(()=>{const ref=peers.value.find(c=>c.id===referenceId.value);if(!ref)return null;const a=cabinetInterval(props.item,axis.value),b=cabinetInterval(ref,axis.value);return side.value==='after'?a.min-b.max:b.min-a.max;});
function apply(mode){emit('arrange',{referenceId:referenceId.value,options:{mode,axis:axis.value,edge:edge.value,side:side.value,gap:gap.value}});}
</script>
<template><section aria-label="Cabinet alignment and spacing"><h3>Alignment and spacing</h3><p v-if="!peers.length" class="hint">Add a second cabinet to use arrangement tools.</p><template v-else><label>Reference cabinet<select v-model="referenceId" aria-label="Reference cabinet"><option v-for="peer in peers" :key="peer.id" :value="peer.id">{{ peer.name }}</option></select></label><label>Arrangement axis<select v-model="axis" aria-label="Arrangement axis"><option value="x">World X</option><option value="z">World Z</option></select></label><label>Alignment edge<select v-model="edge" aria-label="Alignment edge"><option value="min">Minimum edge</option><option value="center">Centre</option><option value="max">Maximum edge</option></select></label><button @click="apply('align')">Align cabinet to reference</button><label>Spacing side<select v-model="side" aria-label="Spacing side"><option value="after">After reference (+ axis)</option><option value="before">Before reference (− axis)</option></select></label><label>Cabinet gap metres<input v-model.number="gap" type="number" min="0" max="10" step="0.001"></label><p v-if="projectedGap!==null" class="hint" data-testid="projected-cabinet-gap">Current projected gap {{ projectedGap.toFixed(3) }} m</p><button @click="apply('gap')">Set cabinet gap</button><p class="hint">Moves only the selected cabinet along the chosen world axis. Edges use rotated body bounds, excluding handles and door swings. Exact settings bypass grid snapping. Invalid moves are rejected; each valid change is one undo step.</p></template></section></template>
